class Note implements java.io.Serializable {
    private static final long serialVersionUID = 1L;
    String text;
    Note(String text) { this.text = text; }
}
public class Main {
    public static void main(String[] args) throws Exception {
        var path = java.nio.file.Path.of("sample.bin");
        try (var out = new java.io.ObjectOutputStream(java.nio.file.Files.newOutputStream(path))) {
            out.writeObject(new Note("Пример"));
        }
        try (var input = new java.io.ObjectInputStream(java.nio.file.Files.newInputStream(path))) {
            Note restored = (Note) input.readObject();
            System.out.println(restored.text);
        }
    }
}

